class SmsSender { send(msg:string){} }
class Logger { log(msg:string){} }

class NotificationGateway {
  notifyAll(msg:string){
    new Logger().log(msg);
    new EmailSender().send(msg);
    new SmsSender().send(msg);
  }
}

new NotificationGateway().notifyAll('Order placed');

class PaymentGateway { charge(order:any){} }
class InventoryService { reserve(items:any){} }
class EmailService { send(order:any){} }

class CheckoutFacade {
  checkout(order:any){
    new InventoryService().reserve(order.items);
    new PaymentGateway().charge(order);
    new EmailService().send(order);
  }
}

class OrderController { place(order:any){ return new CheckoutFacade().checkout(order); } }

